  1→apiVersion: apps/v1
  2→kind: Deployment
  3→metadata:
  4→  name: {{ include "app.fullname" . }}
  5→  labels:
  6→    {{- include "app.labels" . | nindent 4 }}
  7→spec:
  8→  {{- if not .Values.autoscaling.enabled }}
  9→  replicas: {{ .Values.replicaCount }}
 10→  {{- end }}
 11→  selector:
 12→    matchLabels:
 13→      {{- include "app.selectorLabels" . | nindent 6 }}
 14→  {{- with .Values.deploymentStrategy }}
 15→  strategy:
 16→    {{- toYaml . | trim | nindent 4 }}
 17→  {{- end }}
 18→  template:
 19→    metadata:
 20→      {{- with .Values.podAnnotations }}
 21→      annotations:
 22→        {{- toYaml . | nindent 8 }}
 23→      {{- end }}
 24→      labels:
 25→        {{- include "app.selectorLabels" . | nindent 8 }}
 26→    spec:
 27→      {{- with .Values.imagePullSecrets }}
 28→      imagePullSecrets:
 29→        {{- toYaml . | nindent 8 }}
 30→      {{- end }}
 31→      serviceAccountName: {{ include "app.serviceAccountName" . }}
 32→      securityContext:
 33→        {{- toYaml .Values.podSecurityContext | nindent 8 }}
 34→      volumes:
 35→        - name: data
 36→            {{- if .Values.persistence.enabled }}
 37→          persistentVolumeClaim:
 38→            claimName: {{ .Values.persistence.existingClaim | default (include "app.fullname" .) }}
 39→            {{- else }}
 40→          emptyDir: { }
 41→            {{- end }}
 42→      containers:
 43→        - name: {{ .Chart.Name }}
 44→          securityContext:
 45→            {{- toYaml .Values.securityContext | nindent 12 }}
 46→          image: "{{ .Values.image.repository }}:{{ default .Chart.AppVersion .Values.image.tag }}"
 47→          imagePullPolicy: {{ .Values.image.pullPolicy }}
 48→          ports:
 49→            - name: http
 50→              containerPort: {{ .Values.service.port }}
 51→              protocol: TCP
 52→          livenessProbe:
 53→            initialDelaySeconds: {{- if .Values.app.initialDelaySeconds }} {{ .Values.app.initialDelaySeconds }} {{ else }} 60 {{- end }}
 54→            periodSeconds: {{- if .Values.app.periodSeconds }} {{ .Values.app.periodSeconds }} {{ else }} 5 {{- end }}
 55→            httpGet:
 56→              path: {{- if .Values.app.useHealth }} /actuator/health/liveness {{ else }} /api/version {{- end }}
 57→              port: http
 58→              scheme: {{- if .Values.app.useTLS }} HTTPS {{ else }} HTTP {{- end }}
 59→          readinessProbe:
 60→            initialDelaySeconds: {{- if .Values.app.initialDelaySeconds }} {{ .Values.app.initialDelaySeconds }} {{ else }} 60 {{- end }}
 61→            periodSeconds: {{- if .Values.app.periodSeconds }} {{ .Values.app.periodSeconds }} {{ else }} 5 {{- end }}
 62→            httpGet:
 63→              path: {{- if .Values.app.useHealth }} /actuator/health/readiness {{ else }} /api/version {{- end }}
 64→              port: http
 65→              scheme: {{- if .Values.app.useTLS }} HTTPS {{ else }} HTTP {{- end }}
 66→          env:
 67→            {{- range $key, $value := .Values.app.env_vars }}
 68→            - name: {{ $key }}
 69→              value: {{ $value | quote}}{{- end }}
 70→            - name: SPRING_PROFILE
 71→              valueFrom:
 72→                configMapKeyRef:
 73→                  name: {{ include "app.fullname" . }}-config
 74→                  key: SPRING_PROFILE
 75→            - name: CLUSTER_NAME
 76→              valueFrom:
 77→                configMapKeyRef:
 78→                  name: {{ include "app.fullname" . }}-config
 79→                  key: cluster.name
 80→            - name: NAMESPACE_NAME
 81→              valueFrom:
 82→                fieldRef:
 83→                  fieldPath: metadata.namespace
 84→            - name: APPLICATION_NAME
 85→              valueFrom:
 86→                configMapKeyRef:
 87→                  name: {{ include "app.fullname" . }}-config
 88→                  key: application.name
 89→            - name: OTLP_ENDPOINT
 90→              valueFrom:
 91→                configMapKeyRef:
 92→                  name: {{ include "app.fullname" . }}-config
 93→                  key: otlp.endpoint
 94→            - name: OTLP_PROTOCOL
 95→              valueFrom:
 96→                configMapKeyRef:
 97→                  name: {{ include "app.fullname" . }}-config
 98→                  key: otlp.protocol
 99→            - name: OTEL_TRACES_SAMPLER_ARG
100→              valueFrom:
101→                configMapKeyRef:
102→                  name: {{ include "app.fullname" . }}-config
103→                  key: otel.traces.sampler.arg
104→          args:
105→            - $(SPRING_PROFILE)
106→          volumeMounts:
107→            - name: data
108→              mountPath: /var/data
109→          resources:
110→            {{- toYaml .Values.resources | nindent 12 }}
111→      {{- with .Values.nodeSelector }}
112→      nodeSelector:
113→        {{- toYaml . | nindent 8 }}
114→      {{- end }}
115→      {{- with .Values.affinity }}
116→      affinity:
117→        {{- toYaml . | nindent 8 }}
118→      {{- end }}
119→      {{- with .Values.tolerations }}
120→      tolerations:
121→        {{- toYaml . | nindent 8 }}
122→      {{- end }}
